const axios = require('axios');
const authService = require('./auth');
const EventEmitter = require('events');
const express = require('express');
const logger = require('./logger');

class WebSubService extends EventEmitter {
  constructor() {
    super();
    this.isSubscribed = false;
    this.callbackUrl = '';
    this.config = {
      hubUrl: process.env.MOSIP_WEBSUB_URL || '',
      topic: process.env.MOSIP_TOPIC || '',
      callbackPath: process.env.CALLBACK_PATH || '/callback/notifyEvent',
      secret: process.env.MOSIP_WEBSUB_SECRET || '',
      port: process.env.PORT || 3000
    };
    this.router = express.Router();
    this._setupRouter();
  }

  updateConfig(config) {
    if (config) {
      Object.assign(this.config, config);
      logger.debug('WebSub configuration updated', { config: this.config });
    }
    return this;
  }

  setCallbackUrl(baseUrl) {
    this.callbackUrl = `${baseUrl}${this.config.callbackPath}`;
    logger.info(`Callback URL set to: ${this.callbackUrl}`);
    return this;
  }

  async ensureAuthenticated() {
    if (!authService.isAuthenticated()) {
      await authService.authenticate();
    }
    return authService.getToken();
  }

  getRouter() {
    return this.router;
  }

  _setupRouter() {
    // Handle WebSub verification (GET request)
    this.router.get(this.config.callbackPath, (req, res) => {
      this.handleVerification(req, res);
    });
    
    // Handle WebSub notifications (POST request)
    this.router.post(this.config.callbackPath, (req, res) => {
      this.handleNotification(req, res);
    });
    
    logger.debug('WebSub router paths configured', { callbackPath: this.config.callbackPath });
  }

  async subscribe() {
    try {
      if (!this.callbackUrl) {
        throw new Error('Callback URL not set. Please set it before subscribing.');
      }

      if (!this.config.hubUrl) {
        throw new Error('WebSub hub URL not configured');
      }

      if (!this.config.topic) {
        throw new Error('WebSub topic not configured');
      }

      logger.info(`Subscribing to topic: ${this.config.topic}`);
      logger.info(`Using callback URL: ${this.callbackUrl}`);
      
      const token = await this.ensureAuthenticated();
      
      const headers = {
        'Content-Type': 'application/x-www-form-urlencoded',
        'Authorization': token,
        'Cookie': `Authorization=${token}`
      };
      
      const formData = new URLSearchParams();
      formData.append('hub.mode', 'subscribe');
      formData.append('hub.topic', this.config.topic);
      formData.append('hub.callback', this.callbackUrl);
      formData.append('hub.secret', this.config.secret);
      
      logger.debug('Sending subscription request', {
        topic: this.config.topic,
        hubUrl: this.config.hubUrl
      });
      
      const response = await axios.post(this.config.hubUrl, formData, { headers });
      
      if (response.status === 202 || response.status === 200) {
        logger.info(`Subscription successful for topic: ${this.config.topic}`);
        this.isSubscribed = true;
        this.emit('status', 'subscribed');
        return response;
      } else {
        throw new Error(`Unexpected response status: ${response.status}`);
      }
    } catch (error) {
      logger.error('Subscription failed', { error: error.message });
      
      if (error.response) {
        logger.error('Subscription response details', {
          status: error.response.status,
          data: error.response.data
        });
      }
      
      this.emit('status', 'subscription_failed');
      throw error;
    }
  }

  async unsubscribe() {
    try {
      if (!this.config.hubUrl) {
        throw new Error('WebSub hub URL not configured');
      }

      if (!this.config.topic) {
        throw new Error('WebSub topic not configured');
      }
      
      logger.info(`Unsubscribing from topic: ${this.config.topic}`);
      
      const token = await this.ensureAuthenticated();
      
      const headers = {
        'Content-Type': 'application/x-www-form-urlencoded',
        'Authorization': token,
        'Cookie': `Authorization=${token}`
      };
      
      const formData = new URLSearchParams();
      formData.append('hub.mode', 'unsubscribe');
      formData.append('hub.topic', this.config.topic);
      formData.append('hub.callback', this.callbackUrl);
      
      logger.debug('Sending unsubscription request');
      
      const response = await axios.post(this.config.hubUrl, formData, { headers });
      
      if (response.status === 202 || response.status === 200) {
        logger.info(`Unsubscription successful for topic: ${this.config.topic}`);
        this.isSubscribed = false;
        this.emit('status', 'unsubscribed');
        return response;
      } else {
        throw new Error(`Unexpected response status: ${response.status}`);
      }
    } catch (error) {
      logger.error('Unsubscription failed', { error: error.message });
      
      if (error.response) {
        logger.error('Unsubscription response details', {
          status: error.response.status,
          data: error.response.data
        });
      }
      
      this.emit('status', 'unsubscription_failed');
      throw error;
    }
  }

  getStatus() {
    return {
      status: 'UP',
      subscribed: this.isSubscribed,
      topic: this.config.topic,
      hubUrl: this.config.hubUrl,
      callbackUrl: this.callbackUrl,
      authenticated: authService.isAuthenticated()
    };
  }

  handleVerification(req, res) {
    logger.info('Received verification request', { query: req.query });
    
    const mode = req.query['hub.mode'];
    const topic = req.query['hub.topic'];
    const challenge = req.query['hub.challenge'];
    
    if (mode === 'subscribe' && topic === this.config.topic) {
      this.isSubscribed = true;
      logger.info(`Subscription VERIFIED! Topic: ${topic}`);
      this.emit('status', 'subscription_verified');
      return res.status(200).send(challenge);
    } else if (mode === 'unsubscribe' && topic === this.config.topic) {
      this.isSubscribed = false;
      logger.info(`Unsubscription verified for topic: ${topic}`);
      this.emit('status', 'unsubscription_verified');
      return res.status(200).send(challenge);
    } else {
      logger.warn('Invalid verification request', { 
        mode, 
        topic,
        expectedTopic: this.config.topic
      });
      return res.status(404).send('Invalid request');
    }
  }

  handleNotification(req, res) {
    logger.info('NOTIFICATION RECEIVED!');
    logger.debug('Notification body', { body: req.body });
    
    try {
      // Emit status event for notification received
      this.emit('status', 'notification_received');
      
      // Emit the notification event with the raw request data
      this.emit('notification', req.body);
      
      // Return 200 status to acknowledge receipt
      return res.status(200).send('Notification received');
    } catch (error) {
      logger.error('Error handling notification', { 
        error: error.message,
        stack: error.stack 
      });
      
      // Emit error status
      this.emit('status', 'notification_error');
      return res.status(500).send('Error processing notification');
    }
  }
}

module.exports = new WebSubService(); 